// uScript List Box runtime helper.
// A List Box on the canvas reads or writes one item of a list, picked by position or by key.
// Graph code generated by uScript calls these functions; they are safe with null lists and missing items.
//
// Positions start at 1 (1 = first item). Negative positions count from the end (-1 = last item).
// Keys are for "name, value, name, value" string lists: the item after the key is the value.

using System;
using System.Globalization;

public static class uScript_ListBox
{
   // ---------------------------------------------------------------- selectors

   /// <summary>Turns a position from a variable of any number or text type into a whole number.</summary>
   public static int Position(int value) { return value; }

   public static int Position(float value) { return (int)Math.Round(value); }

   public static int Position(double value) { return (int)Math.Round(value); }

   public static int Position(string value)
   {
      int result;
      if (int.TryParse((value ?? string.Empty).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out result)) return result;
      return 0;
   }

   public static int Position(object value)
   {
      if (value == null) return 0;
      if (value is int) return (int)value;
      if (value is float) return Position((float)value);
      if (value is double) return Position((double)value);
      return Position(value.ToString());
   }

   /// <summary>Turns a key from a variable of any type into text.</summary>
   public static string Key(object value)
   {
      if (value == null) return string.Empty;
      if (value is IFormattable) return ((IFormattable)value).ToString(null, CultureInfo.InvariantCulture);
      return value.ToString();
   }

   /// <summary>The array index for a position (1 = first, -1 = last), or -1 when it is outside the list.</summary>
   public static int IndexOf(int length, int position)
   {
      if (length <= 0 || position == 0) return -1;
      int index = position > 0 ? position - 1 : length + position;
      return index >= 0 && index < length ? index : -1;
   }

   /// <summary>The array index of the value that follows a key, or -1 when the key is missing or has no value after it.</summary>
   public static int ValueIndexOfKey(string[] list, string key)
   {
      if (list == null || key == null) return -1;
      string wanted = key.Trim();

      for (int i = 0; i + 1 < list.Length; i++)
      {
         if (list[i] != null && string.Equals(list[i].Trim(), wanted, StringComparison.OrdinalIgnoreCase))
         {
            return i + 1;
         }
      }

      return -1;
   }

   // ---------------------------------------------------------------- reading any list by position

   public static T Get<T>(T[] list, int position)
   {
      if (list == null) return default(T);
      int index = IndexOf(list.Length, position);
      return index >= 0 ? list[index] : default(T);
   }

   // ---------------------------------------------------------------- reading a string list, converted

   public static string GetString(string[] list, int position)
   {
      if (list == null) return string.Empty;
      int index = IndexOf(list.Length, position);
      return index >= 0 ? (list[index] ?? string.Empty) : string.Empty;
   }

   public static string GetString(string[] list, string key)
   {
      int index = ValueIndexOfKey(list, key);
      return index >= 0 ? (list[index] ?? string.Empty) : string.Empty;
   }

   public static int GetInt(string[] list, int position) { return ToInt(GetString(list, position)); }

   public static int GetInt(string[] list, string key) { return ToInt(GetString(list, key)); }

   public static float GetFloat(string[] list, int position) { return ToFloat(GetString(list, position)); }

   public static float GetFloat(string[] list, string key) { return ToFloat(GetString(list, key)); }

   public static bool GetBool(string[] list, int position) { return ToBool(GetString(list, position)); }

   public static bool GetBool(string[] list, string key) { return ToBool(GetString(list, key)); }

   // ---------------------------------------------------------------- writing

   /// <summary>Writes an item of any list by position. Positions outside the list are ignored.</summary>
   public static void Set<T>(T[] list, int position, T value)
   {
      if (list == null) return;
      int index = IndexOf(list.Length, position);
      if (index >= 0) list[index] = value;
   }

   /// <summary>Writes a string list item by position, as text. Positions outside the list are ignored.</summary>
   public static void SetText(string[] list, int position, object value)
   {
      if (list == null) return;
      int index = IndexOf(list.Length, position);
      if (index >= 0) list[index] = Key(value);
   }

   /// <summary>Writes the value after a key, as text. A missing key is ignored (add new keys with a list node).</summary>
   public static void SetText(string[] list, string key, object value)
   {
      int index = ValueIndexOfKey(list, key);
      if (index >= 0) list[index] = Key(value);
   }

   // ---------------------------------------------------------------- conversions (the same on every PC, whatever its number format)

   public static float ToFloat(string text)
   {
      if (string.IsNullOrEmpty(text)) return 0f;
      text = text.Trim();

      float result;
      if (float.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out result)) return result;

      // "12,5" written on a PC that uses commas for decimals
      if (text.IndexOf('.') < 0 && float.TryParse(text.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out result)) return result;

      // a number with a unit after it, such as "12.5m" or "30%"
      int end = 0;
      while (end < text.Length && (char.IsDigit(text[end]) || text[end] == '.' || text[end] == ',' || (end == 0 && (text[end] == '-' || text[end] == '+')))) end++;
      if (end > 0 && float.TryParse(text.Substring(0, end).Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out result)) return result;

      return 0f;
   }

   public static int ToInt(string text)
   {
      if (string.IsNullOrEmpty(text)) return 0;

      int result;
      if (int.TryParse(text.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out result)) return result;

      return (int)Math.Round(ToFloat(text));
   }

   public static bool ToBool(string text)
   {
      if (string.IsNullOrEmpty(text)) return false;
      text = text.Trim();

      bool result;
      if (bool.TryParse(text, out result)) return result;

      return text == "1" || string.Equals(text, "yes", StringComparison.OrdinalIgnoreCase) || string.Equals(text, "on", StringComparison.OrdinalIgnoreCase);
   }
}

/// <summary>How a List Box picks its item.</summary>
public enum uScript_ListBoxFindBy
{
   Position,
   Key
}

/// <summary>What a List Box on a string list gives out.</summary>
public enum uScript_ListBoxOutput
{
   Text,
   WholeNumber,
   Decimal,
   TrueFalse
}
